"use client";

import React, { useState } from "react";
import {
    FileText, ShieldCheck, Share2, PenTool, 
    Users, Lock, Globe, FileBadge, 
    Download, Trash2, Eye, Plus, 
    History, AlertTriangle, CheckCircle, Printer,
    QrCode, Key
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";

/* --- Advanced Types --- */
type DocContext = "Personal" | "Dependent" | "Corporate" | "Financial";

interface AdvancedDoc {
    id: string;
    name: string;
    context: DocContext;
    status: "Verified" | "Action Required" | "Signed" | "Shared";
    security: "Encrypted" | "Public-Link" | "Internal";
    expiry?: string;
    lastAccessed?: string;
}

const eliteDocs: AdvancedDoc[] = [
    { id: "1", name: "Passport_Self.pdf", context: "Personal", status: "Verified", security: "Encrypted", expiry: "2029-05-12" },
    { id: "2", name: "Spouse_Health_Card.pdf", context: "Dependent", status: "Verified", security: "Internal" },
    { id: "3", name: "FY26_Tax_Declaration.pdf", context: "Financial", status: "Action Required", security: "Encrypted" },
    { id: "4", name: "Remote_Work_Policy.pdf", context: "Corporate", status: "Signed", security: "Internal", lastAccessed: "Today" },
];

export default function EliteDocumentHub() {
    return (
        <div className="p-6 lg:p-10 space-y-8 bg-[#F8F9FB] dark:bg-[#020408] min-h-screen">
            
            {/* 1. THE COMMAND CENTER HEADER */}
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                {/* Compliance HUD */}
                <div className="lg:col-span-2 bg-white dark:bg-gray-900 rounded-[2.5rem] p-8 border border-gray-100 dark:border-gray-800 shadow-sm flex items-center justify-between overflow-hidden relative">
                    <div className="relative z-10">
                        <div className="flex items-center gap-2 mb-2">
                            <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Audit Readiness</span>
                        </div>
                        <h2 className="text-4xl font-black tracking-tighter italic">Elite Status</h2>
                        <p className="text-xs text-gray-500 font-bold mt-2">All mandatory corporate filings are up to date.</p>
                    </div>
                    <ShieldCheck className="absolute -right-6 -bottom-6 w-32 h-32 text-emerald-500/5 rotate-12" />
                </div>

                {/* Quick Action Bento Boxes */}
                <div className="bg-brand-600 rounded-[2.5rem] p-6 text-white flex flex-col justify-between">
                    <p className="text-[10px] font-black uppercase opacity-60">External Access</p>
                    <h3 className="text-lg font-bold leading-tight">Secure Share Link</h3>
                    <button className="bg-white/10 hover:bg-white/20 text-white py-2 rounded-xl text-[10px] font-black uppercase mt-4 border border-white/10">Generate One-Time URL</button>
                </div>

                <div className="bg-gray-900 rounded-[2.5rem] p-6 text-white flex flex-col justify-between">
                    <p className="text-[10px] font-black uppercase opacity-60">Self-Service</p>
                    <h3 className="text-lg font-bold leading-tight">Certificate Center</h3>
                    <button className="bg-brand-500 py-2 rounded-xl text-[10px] font-black uppercase mt-4 shadow-lg shadow-brand-500/20">Instnt Issuance</button>
                </div>
            </div>

            {/* 2. THE MULTI-CONTEXT NAV */}
            <div className="flex flex-wrap gap-4 items-center justify-between bg-white dark:bg-gray-900 p-3 rounded-[2rem] border border-gray-100 dark:border-gray-800 shadow-sm">
                <div className="flex gap-2">
                    {["All", "Personal", "Dependent", "Corporate", "Financial"].map(tab => (
                        <button key={tab} className="px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all hover:bg-gray-50 dark:hover:bg-gray-800 active:scale-95">
                            {tab}
                        </button>
                    ))}
                </div>
                <button className="bg-gray-900 dark:bg-brand-600 text-white px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2">
                   <Plus size={16} /> Encrypted Upload
                </button>
            </div>

            {/* 3. INTELLIGENT DATA TABLE */}
            <div className="bg-white dark:bg-gray-900 rounded-[3rem] border border-gray-100 dark:border-gray-800 overflow-hidden shadow-sm">
                <table className="w-full text-left">
                    <thead>
                        <tr className="bg-gray-50/50 dark:bg-gray-800/50 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
                            <th className="px-8 py-5">File Signature</th>
                            <th className="px-8 py-5">Lifecycle Status</th>
                            <th className="px-8 py-5">Security Level</th>
                            <th className="px-8 py-5 text-right">Ops</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
                        {eliteDocs.map((doc) => (
                            <tr key={doc.id} className="group hover:bg-gray-50/50 transition-all duration-300">
                                <td className="px-8 py-6">
                                    <div className="flex items-center gap-5">
                                        <div className="w-12 h-12 bg-gray-50 dark:bg-gray-800 rounded-2xl flex items-center justify-center text-gray-400 group-hover:text-brand-500 transition-colors shadow-inner">
                                            <FileText size={22} />
                                        </div>
                                        <div>
                                            <h4 className="text-sm font-black text-gray-900 dark:text-white group-hover:underline underline-offset-4 cursor-pointer">{doc.name}</h4>
                                            <p className="text-[10px] font-bold text-gray-400 uppercase flex items-center gap-2 mt-1">
                                                {doc.context} {doc.expiry && <span className="text-red-500">• Expires {doc.expiry}</span>}
                                            </p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-8 py-6">
                                    <div className="flex flex-col gap-1">
                                       <StatusBadge status={doc.status} />
                                       {doc.lastAccessed && <span className="text-[9px] font-bold text-gray-400">Last seen {doc.lastAccessed}</span>}
                                    </div>
                                </td>
                                <td className="px-8 py-6">
                                    <div className="flex items-center gap-2">
                                        {doc.security === "Encrypted" ? <Lock size={12} className="text-brand-600" /> : <Globe size={12} className="text-gray-400" />}
                                        <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-400">{doc.security}</span>
                                    </div>
                                </td>
                                <td className="px-8 py-6 text-right">
                                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all">
                                        <ActionButton icon={<QrCode />} title="Verify via QR" />
                                        <ActionButton icon={<PenTool />} title="Digital Signature" />
                                        <ActionButton icon={<Share2 />} title="External Access" />
                                        <ActionButton icon={<History />} title="Audit Trail" />
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

/* --- REUSABLE COMPONENTS --- */

const ActionButton = ({ icon, title }: any) => (
    <button className="p-2.5 text-gray-400 hover:text-brand-600 hover:bg-white dark:hover:bg-gray-800 rounded-xl transition-all shadow-sm border border-transparent hover:border-gray-100" title={title}>
        {React.cloneElement(icon, { size: 16 })}
    </button>
);

const StatusBadge = ({ status }: { status: string }) => {
    const styles: any = {
        Verified: "text-emerald-600 bg-emerald-50",
        Signed: "text-blue-600 bg-blue-50",
        "Action Required": "text-red-600 bg-red-50 animate-pulse",
        Shared: "text-purple-600 bg-purple-50",
    };
    return (
        <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${styles[status]}`}>
            {status}
        </span>
    );
};